/*
 * A268780  Number of n X 7 binary arrays with some element plus some
 *          horizontally, vertically, diagonally or antidiagonally adjacent
 *          neighbor totalling two no more than once.
 * https://oeis.org/A268780
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   Number of n X 7 binary arrays with at most one adjacent pair of
 *            1’s * (adjacent horizontally, vertically, diagonally or
 *            anti‑diagonally). * * The sequence is generated by dynamic
 *            programming over rows. * - Each row is a 7‑bit pattern. * -
 *            Patterns with more than one horizontal 1‑1 pair are discar...
 * Range:     u8 n <= 1, u16 n <= 3, u32 n <= 8, u64 n <= 18, u128 n <= 38,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

/* --------------------------------------------------------------------- */
/*  Precomputed data                                              */
/* --------------------------------------------------------------------- */
#define WIDTH 7
#define PATTS  (1 << WIDTH)          /* 128 patterns */

static uint8_t hpair[PATTS];        /* horizontal 1‑1 pairs in a pattern */
static uint8_t cross[PATTS][PATTS]; /* vertical + diagonal pairs between two patterns */

/* For each previous pattern we store the indices of
   patterns that are reachable with 0 or 1 new pairs.           */
static uint8_t  r0cnt[PATTS];                /* number of r with npairs==0 */
static uint8_t  r1cnt[PATTS];                /* number of r with npairs==1 */
static short    r0list[PATTS][PATTS];        /* indices of r where npairs==0 */
static short    r1list[PATTS][PATTS];        /* indices of r where npairs==1 */

static seq_t base_val[19];  /* base_val[1..18]  */
static bool data_ready = false;

/* --------------------------------------------------------------------- */
/*  Helper: initialise static transition tables and base values          */
/* --------------------------------------------------------------------- */
static void init_precompute(void)
{
    if (data_ready) return;
    data_ready = true;

    /* precompute horizontal pairs for each pattern */
    for (int p = 0; p < PATTS; ++p) {
        unsigned count = 0;
        for (int j = 0; j < WIDTH-1; ++j)
            if ( ((p >> j) & 1) && ((p >> (j+1)) & 1) )
                ++count;
        hpair[p] = (uint8_t)count;
    }

    /* precompute cross pairs (vertical + two diagonals) between every pair */
    const uint16_t mask = PATTS - 1;
    for (int a = 0; a < PATTS; ++a) {
        for (int b = 0; b < PATTS; ++b) {
            unsigned v = __builtin_popcount(a & b);           /* vertical */
            v += __builtin_popcount( (a >> 1) & b );         /* diagonal right  */
            v += __builtin_popcount( ((a << 1) & mask) & b );/* diagonal left   */
            cross[a][b] = (uint8_t)v;
        }
    }

    /* build transition lists */
    for (int a = 0; a < PATTS; ++a) {
        r0cnt[a] = r1cnt[a] = 0;
        for (int b = 0; b < PATTS; ++b) {
            unsigned np = (unsigned)hpair[b] + (unsigned)cross[a][b];
            if (np == 0) {
                r0list[a][r0cnt[a]++] = (short)b;
            } else if (np == 1) {
                r1list[a][r1cnt[a]++] = (short)b;
            }
        }
    }

    /* ----------------------------------------------------------------- */
    /*  Compute base values a(1)..a(18) using the DP described above     */
    /* ----------------------------------------------------------------- */
    seq_t dp0[PATTS], dp1[PATTS], ndp0[PATTS], ndp1[PATTS];

    /* initialise to zero */
    for (int i = 0; i < PATTS; ++i) {
        dp0[i] = 0;
        dp1[i] = 0;
    }

    /* first row */
    seq_t sum0 = 0, sum1 = 0;
    for (int r = 0; r < PATTS; ++r) {
        if (hpair[r] > 1) continue;
        if (hpair[r] == 0) { dp0[r] = 1; ++sum0; }
        else               { dp1[r] = 1; ++sum1; }
    }
    base_val[1] = sum0 + sum1;  /* should be 72 */

    for (int row = 2; row <= 18; ++row) {
        for (int i = 0; i < PATTS; ++i) {
            ndp0[i] = 0;
            ndp1[i] = 0;
        }
        for (int p = 0; p < PATTS; ++p) {
            seq_t val0 = dp0[p];
            seq_t val1 = dp1[p];
            if (val0 == 0 && val1 == 0) continue;

            /* transitions from state 0 */
            if (val0 != 0) {
                for (uint8_t k = 0; k < r0cnt[p]; ++k) {
                    short r = r0list[p][k];
                    ndp0[r] += val0;
                }
                for (uint8_t k = 0; k < r1cnt[p]; ++k) {
                    short r = r1list[p][k];
                    ndp1[r] += val0;
                }
            }

            /* transitions from state 1 (only npairs==0 allowed) */
            if (val1 != 0) {
                for (uint8_t k = 0; k < r0cnt[p]; ++k) {
                    short r = r0list[p][k];
                    ndp1[r] += val1;
                }
            }
        }
        /* copy back */
        for (int i = 0; i < PATTS; ++i) {
            dp0[i] = ndp0[i];
            dp1[i] = ndp1[i];
        }

        /* total for this row */
        seq_t total = 0;
        for (int i = 0; i < PATTS; ++i) {
            total += dp0[i];
            total += dp1[i];
        }
        base_val[row] = total;
    }
}

/* --------------------------------------------------------------------- */
/*  Main sequence function                                              */
/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    init_precompute();              /* ensure tables and base values are ready */

    if (n <= 18) return base_val[n];

    /* DP for rows 2..n */
    seq_t dp0[PATTS], dp1[PATTS], ndp0[PATTS], ndp1[PATTS];

    for (int i = 0; i < PATTS; ++i) {
        dp0[i] = dp1[i] = 0;
    }

    /* first row (row 1) */
    for (int r = 0; r < PATTS; ++r) {
        if (hpair[r] > 1) continue;
        if (hpair[r] == 0) dp0[r] = 1;
        else               dp1[r] = 1;
    }

    for (int row = 2; row <= n; ++row) {
        for (int i = 0; i < PATTS; ++i) {
            ndp0[i] = 0;
            ndp1[i] = 0;
        }
        for (int p = 0; p < PATTS; ++p) {
            seq_t val0 = dp0[p];
            seq_t val1 = dp1[p];
            if (val0 == 0 && val1 == 0) continue;

            /* from state 0 */
            if (val0 != 0) {
                for (uint8_t k = 0; k < r0cnt[p]; ++k) {
                    short r = r0list[p][k];
                    ndp0[r] += val0;
                }
                for (uint8_t k = 0; k < r1cnt[p]; ++k) {
                    short r = r1list[p][k];
                    ndp1[r] += val0;
                }
            }

            /* from state 1 */
            if (val1 != 0) {
                for (uint8_t k = 0; k < r0cnt[p]; ++k) {
                    short r = r0list[p][k];
                    ndp1[r] += val1;
                }
            }
        }
        /* copy back */
        for (int i = 0; i < PATTS; ++i) {
            dp0[i] = ndp0[i];
            dp1[i] = ndp1[i];
        }
    }

    /* sum everything to get a(n) */
    seq_t result = 0;
    for (int i = 0; i < PATTS; ++i) {
        result += dp0[i];
        result += dp1[i];
    }
    return result;
}
